func TestCreateCustomerRejectsOversizedJSONBeforeService(t *testing.T) {
	const limit = 2 << 20
	tests := []struct{ name, body string }{
		{"first value", `{"name":"` + strings.Repeat("x", limit) + `"}`},
		{"trailing whitespace", `{"name":"customer"}` + strings.Repeat(" ", limit)},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// No CRM service or DB is available: this must return at input decoding.
			s := &Server{}
			r := httptest.NewRequest(http.MethodPost, "/api/v1/customers", io.NopCloser(strings.NewReader(tt.body)))
			r = r.WithContext(httpx.WithRequestID(r.Context(), "customer-request"))
			w := httptest.NewRecorder()
			s.createCustomer(w, r)
			if w.Code != http.StatusRequestEntityTooLarge {
				t.Errorf("status = %d, want 413", w.Code)
			}
			var envelope struct {
				Error httpx.Error `json:"error"`
			}
			if err := json.Unmarshal(w.Body.Bytes(), &envelope); err != nil {
				t.Fatal(err)
			}
			if envelope.Error.Code != "request_too_large" || envelope.Error.RequestID != "customer-request" {
				t.Errorf("error = %+v, want request_too_large and preserved requestId", envelope.Error)
			}
		})
	}
}
package httpx

import (
	"encoding/json"
	"errors"
	"io"
	"net"
	"net/http"
	"net/netip"
	"strconv"
	"strings"
)

type Error struct {
	Code      string         `json:"code"`
	Message   string         `json:"message"`
	Details   map[string]any `json:"details,omitempty"`
	RequestID string         `json:"requestId,omitempty"`
}

type errorEnvelope struct {
	Error Error `json:"error"`
}

func JSON(w http.ResponseWriter, status int, value any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(value)
}

func ErrorJSON(w http.ResponseWriter, r *http.Request, status int, code, message string, details map[string]any) {
	JSON(w, status, errorEnvelope{Error: Error{Code: code, Message: message, Details: details, RequestID: RequestID(r.Context())}})
}

func DecodeJSON(w http.ResponseWriter, r *http.Request, target any) bool {
	r.Body = http.MaxBytesReader(w, r.Body, 2<<20)
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(target); err != nil {
		var max *http.MaxBytesError
		if errors.As(err, &max) {
			ErrorJSON(w, r, http.StatusRequestEntityTooLarge, "request_too_large", "요청 본문이 너무 큽니다.", nil)
			return false
		}
		ErrorJSON(w, r, http.StatusBadRequest, "invalid_json", "JSON 요청 형식이 올바르지 않습니다.", map[string]any{"cause": err.Error()})
		return false
	}
	if err := dec.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		var max *http.MaxBytesError
		if errors.As(err, &max) {
			ErrorJSON(w, r, http.StatusRequestEntityTooLarge, "request_too_large", "요청 본문이 너무 큽니다.", nil)
			return false
		}
		ErrorJSON(w, r, http.StatusBadRequest, "invalid_json", "요청에는 JSON 객체 하나만 허용됩니다.", nil)
		return false
	}
	return true
}

// ClientIP is the address a request arrived from, canonicalised so that it is
// both a stable key and a value PostgreSQL accepts for an `inet` column.
//
// Every caller that stores it binds it into an `::inet` cast that maps only the
// empty string to NULL, and an address the cast refuses does not lose one
// column — it fails the whole statement. That drops the audit event,
// LOGIN_FAILED included, and in auth.Login it fails the session insert, so the
// client cannot log in at all.
// RemoteAddr carries the zone of a link-local address (`[fe80::1%eth0]:52000`),
// which `inet` rejects, so the zone is dropped here; an address that is not an
// address at all (a Unix socket peer is "@") becomes "" and is stored as NULL
// instead of taking its row down with it. An IPv4-mapped form is unmapped so
// one client keys and reads the same way on a dual-stack listener.
func ClientIP(r *http.Request) string {
	raw := r.RemoteAddr
	if host, _, err := net.SplitHostPort(raw); err == nil {
		raw = host
	}
	addr, err := netip.ParseAddr(raw)
	if err != nil {
		return ""
	}
	return addr.WithZone("").Unmap().String()
}

func Bearer(r *http.Request) string {
	v := strings.TrimSpace(r.Header.Get("Authorization"))
	if len(v) < 8 || !strings.EqualFold(v[:7], "Bearer ") {
		return ""
	}
	return strings.TrimSpace(v[7:])
}

// IntQuery reads a bounded integer from the query string. A key that is absent,
// is not a decimal integer, or lands outside [min, max] yields fallback.
//
// The parse is strict on purpose. fmt.Sscan stops at the first byte it cannot
// use and reports no error about the rest, so it read "1e3" as 1, "0x10" as 16
// and "50abc" as 50: a caller was answered with a different number than it sent,
// under a schema this server publishes as `type: integer` with a minimum and a
// maximum. Surrounding spaces are still accepted because a query string carries
// a "+" as a space.
func IntQuery(r *http.Request, key string, fallback, min, max int) int {
	n, ok := intQuery(r, key)
	if !ok || n < min || n > max {
		return fallback
	}
	return n
}

// ClampQuery is IntQuery for a filter whose fallback switches the filter off.
// Falling back there answers a request to narrow with everything the caller did
// not ask for, so an out-of-range value is pulled to the nearest bound instead
// and only an unreadable one yields fallback.
func ClampQuery(r *http.Request, key string, fallback, min, max int) int {
	n, ok := intQuery(r, key)
	switch {
	case !ok:
		return fallback
	case n < min:
		return min
	case n > max:
		return max
	}
	return n
}

func intQuery(r *http.Request, key string) (int, bool) {
	v := strings.TrimSpace(r.URL.Query().Get(key))
	if v == "" {
		return 0, false
	}
	n, err := strconv.Atoi(v)
	if err != nil {
		return 0, false
	}
	return n, true
}
package server

import (
	"context"
	"log/slog"
	"net"
	"net/http"
	"net/http/httputil"
	"net/url"
	"strings"
	"time"

	"github.com/hkjang/relio/internal/analytics"
	"github.com/hkjang/relio/internal/platform/httpx"
)

// The Momento same-origin proxy.
//
// A tracker that loads from and reports to the collector's own origin needs
// that origin in script-src and connect-src. Where the policy cannot be widened
// — or where nobody wants an external host in it — the tracker is served from
// /momento/tracker.js and told (data-endpoint="/momento") to post events there
// too, and this handler forwards both to the collector. From the browser's
// point of view everything is same-origin, so `script-src 'self'` stays exactly
// as shipped.
//
// The upstream is only ever a script origin an administrator saved through
// validate(): an exact http(s) host, no wildcard, no path. It is resolved per
// request from the same cached snapshot the policy uses, so disabling the
// provider closes the proxy at the same moment it leaves the header.

// momentoBodyLimit caps what a visitor can push through the proxy. Event
// batches are a few kilobytes; anything larger is not tracking data.
const momentoBodyLimit = 256 << 10

// momentoUpstreamTimeout bounds a request to the collector so a slow collector
// cannot hold Relio's connections — a page must never wait on analytics.
const momentoUpstreamTimeout = 10 * time.Second

// momentoStrippedRequestHeaders never reach the collector. The session cookie is
// the important one: the browser attaches it to every same-origin request, and
// forwarding it would hand every visitor's Relio session to the collector.
var momentoStrippedRequestHeaders = []string{"Cookie", "Authorization", "X-CSRF-Token"}

// momentoStrippedResponseHeaders never reach the browser. A collector must not
// plant cookies on Relio's origin, and its own policy headers would be added to
// (not replace) the ones the middleware already set on this response.
var momentoStrippedResponseHeaders = []string{"Set-Cookie", "Content-Security-Policy", "Content-Security-Policy-Report-Only", "Strict-Transport-Security"}

// momentoProxy builds the /momento/* handler. upstream returns the collector
// origin for this request or "" when the proxy is off, in which case the path
// answers 404 like any other unrouted path — nothing about the collector is
// revealed to a visitor while it is not configured.
func momentoProxy(upstream func(context.Context) string, log *slog.Logger, transport http.RoundTripper) http.Handler {
	if transport == nil {
		transport = momentoTransport()
	}
	proxy := &httputil.ReverseProxy{
		Transport: transport,
		Rewrite: func(r *httputil.ProxyRequest) {
			target := r.In.Context().Value(momentoTargetKey{}).(*url.URL)
			r.SetURL(target)
			// SetURL joins the target path with the incoming one; the incoming
			// path still carries the /momento prefix, which the collector does
			// not know.
			r.Out.URL.Path = strings.TrimPrefix(r.In.URL.Path, analytics.MomentoProxyPath)
			r.Out.URL.RawPath = ""
			if r.Out.URL.Path == "" {
				r.Out.URL.Path = "/"
			}
			r.Out.Host = target.Host
			for _, name := range momentoStrippedRequestHeaders {
				r.Out.Header.Del(name)
			}
			// The collector attributes visits by address; behind the proxy it
			// would otherwise see only Relio.
			r.SetXForwarded()
		},
		ModifyResponse: func(resp *http.Response) error {
			for _, name := range momentoStrippedResponseHeaders {
				resp.Header.Del(name)
			}
			return nil
		},
		ErrorHandler: func(w http.ResponseWriter, r *http.Request, err error) {
			if log != nil {
				log.Warn("momento proxy upstream failed", "error", err, "path", r.URL.Path, "requestId", httpx.RequestID(r.Context()))
			}
			w.WriteHeader(http.StatusBadGateway)
		},
	}
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		origin := upstream(r.Context())
		target, err := url.Parse(origin)
		if origin == "" || err != nil || target.Host == "" {
			http.NotFound(w, r)
			return
		}
		switch r.Method {
		case http.MethodGet, http.MethodHead, http.MethodPost, http.MethodOptions:
		default:
			// The tracker fetches a script and posts events; nothing else
			// belongs on this path.
			w.Header().Set("Allow", "GET, HEAD, POST, OPTIONS")
			w.WriteHeader(http.StatusMethodNotAllowed)
			return
		}
		r.Body = http.MaxBytesReader(w, r.Body, momentoBodyLimit)
		// Analytics responses are per visitor and must never be cached by a
		// shared proxy in front of Relio; the tracker script may be, briefly.
		if r.Method != http.MethodGet && r.Method != http.MethodHead {
			w.Header().Set("Cache-Control", "no-store")
		}
		proxy.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), momentoTargetKey{}, target)))
	})
}

// momentoTargetKey carries the resolved collector from the handler into the
// Rewrite hook, which has no other way to learn it per request.
type momentoTargetKey struct{}

func momentoTransport() http.RoundTripper {
	return &http.Transport{
		Proxy:                 http.ProxyFromEnvironment,
		DialContext:           (&net.Dialer{Timeout: 5 * time.Second}).DialContext,
		ResponseHeaderTimeout: momentoUpstreamTimeout,
		TLSHandshakeTimeout:   5 * time.Second,
		MaxIdleConns:          16,
		IdleConnTimeout:       90 * time.Second,
	}
}

// momentoProxyHandler wires the proxy to the analytics snapshot.
func (s *Server) momentoProxyHandler() http.Handler {
	return momentoProxy(func(ctx context.Context) string {
		if s.Analytics == nil {
			return ""
		}
		return s.Analytics.MomentoUpstream(ctx)
	}, s.Log, nil)
}
